from pathlib import Path
from bs4 import BeautifulSoup
import json,hashlib,datetime,fitz
root=Path('continuation/corporate-ownership');sp=root/'sources.json';sources=json.loads(sp.read_text());claims=[];candidates=[]
def add(id,statement,sourceids,locators,status='verified_as_reported',**kw):
 claims.append(dict(claim_id=id,statement=statement,source_ids=sourceids,locators=locators,status=status,**kw))
# Preserve metadata pointers for already independently collected originals; no duplicate download.
reuse=[('CORP2-REG-SCOUT','evidence/id-finra-scout-151990.pdf','https://files.brokercheck.finra.org/firm/firm_151990.pdf'),('CORP2-REG-OPHIR','evidence/id-sec-ophir-164729-adv.pdf','https://reports.adviserinfo.sec.gov/reports/ADV/164729/PDF/164729.pdf'),('CORP2-REG-ENTRYPOINT','evidence/sec-313946-adv.pdf','https://reports.adviserinfo.sec.gov/reports/ADV/313946/PDF/313946.pdf'),('CORP2-REG-BROCHURE','evidence/parent-entrypoint-brochure-1031410.pdf','https://files.adviserinfo.sec.gov/IAPD/Content/Common/crd_iapd_Brochure.aspx?BRCHR_VRSN_ID=1031410'),('CORP2-NY-DATA-DISCLAIMER','evidence/corp-ny-data-overview.pdf','https://data.ny.gov/api/views/63wc-4exh/files/1f56db38-2cf7-4d11-bf17-c8ae524926d3?download=true&filename=DOS_CorpsEntities_Overview.pdf')]
for id,file,url in reuse:
 raw=Path(file).read_bytes();d=fitz.open(stream=raw,filetype='pdf');sources.append(dict(document_id=id,url=url,file=file,sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw),physical_pdf_pages=len(d),source_class='Previously independently retrieved official PDF; reused without downloading',retrieved_at_utc=None,retrieval_timestamp_note='Original acquisition timestamp remains in earlier investigation source index; null here is deliberate, not a new retrieval.',reused_existing_investigation_evidence=True))
fields={'file_number':'lblFileNumber','formation_date_raw':'lblIncDate','legal_name':'lblEntityName','entity_kind':'lblEntityKind','entity_type':'lblEntityType','residency':'lblResidency','jurisdiction':'lblState','registered_agent_name':'lblAgentName'}
for s in sources:
 file=s.get('file')
 if not file or not Path(file).exists():continue
 raw=Path(file).read_bytes();assert hashlib.sha256(raw).hexdigest()==s['sha256']
 if not file.endswith('.html'):continue
 soup=BeautifulSoup(raw,'html.parser');f=soup.find(id='ctl00_ContentPlaceHolder1_lblFileNumber')
 if not f:continue
 rec={k:soup.find(id='ctl00_ContentPlaceHolder1_'+v).get_text(' ',strip=True) for k,v in fields.items()};rec['formation_date']=datetime.datetime.strptime(rec['formation_date_raw'],'%m/%d/%Y').date().isoformat();rec.update(source_id=s['document_id'],record_scope='Free public entity details, explicitly not statement of good standing. No owners shown.',entity_join_status='corporate_record_found_subject_ownership_join_unproven')
 if rec['file_number']=='10521968':rec['entity_join_status']='not_merged_temporally_incompatible_with_2012_affiliation_without_succession_evidence'
 candidates.append(rec);s['parsed_entity_fields']=rec
 add('CORP2-ENTITY-'+rec['file_number'],f"Delaware public detail record names {rec['legal_name']}, file{rec['file_number']}, formation{rec['formation_date']}, kind{rec['entity_kind']}, residency{rec['residency']}, jurisdiction{rec['jurisdiction']}. Free detail is not good standing or ownership proof.",[s['document_id']],['HTML IDs ctl00_ContentPlaceHolder1_lblFileNumber,lblIncDate,lblEntityName,lblEntityKind,lblResidency,lblState'],status='official_registry_field_observation_subject_join_provisional',candidate=rec)
