add('CORP2-OWN-NAYS','Scout report identifies NAYS LLC as member of Finch25% to less than50% from08/2012; Dror Niv as member of NAYS25% to less than50% from05/2009. Neither a complete cap table nor100% ownership by Dror Niv is established.',['CORP2-REG-SCOUT'],['physical PDF pp8-9 indirect owners'])
add('CORP2-OWN-OPHIR','Ophir ADV filed2017-03-30 identifies Finch LLC as managing member75% or more with status acquired04/2012; MEB NY Inc as managing member of Finch75% or more acquired04/2012; Bleich CRD4262671 as owner of MEB NY75% or more acquired05/2009.',['CORP2-REG-OPHIR'],['physical PDF p1 header, pp19-20 SchedulesA,B'])
add('CORP2-CONFLICT-FINCH','The Ophir2017 ADV reports MEB NY interest in Finch75% or more, while Scout BrokerCheck reports50% to less than75%. Acquisition months04/2012 versus08/2012 do not establish which band is currently correct or prove a dated change. Disclosure snapshot/scope differences remain unresolved.',['CORP2-REG-OPHIR','CORP2-REG-SCOUT'],['Ophir physical PDF pp19-20; Scout physical PDF p8'],status='unresolved_disclosure_variation')
add('CORP2-OWN-ENTRYPOINT','EntryPoint October15,2026 ADV reports EntryPoint PartnersLP as member75% or more from10/2020; EntryPoint GP LLC statusGENERAL PARTNER from10/2020; Bleich CRD4262671 member of GP and limited partner of Partners, both25% to less than50% from07/2023.',['CORP2-REG-ENTRYPOINT'],['physical PDF pp26-27 SchedulesA,B'])
add('CORP2-OWN-TRUST','EntryPoint ScheduleB lists Richard A.Desich Irrevocable2005 SD Trust as member of EntryPoint GP LLC25% to less than50% from11/2024 and South Dakota Trust Company as trustee from12/2020. Professional chain only; no familial or ultimate-beneficiary conclusion.',['CORP2-REG-ENTRYPOINT'],['physical PDF p27 ScheduleB'])
add('CORP2-DOMESTIC-CODE','In ADV ownership schedules, DE denotes domestic entity, FE foreign entity, I individual; DE is not proof of Delaware incorporation.',['CORP2-REG-OPHIR','CORP2-REG-ENTRYPOINT'],['Ophir physical PDF pp19-20 instructions4; EntryPoint physical PDF pp26-27 instructions4'])
add('CORP2-LEGALFORM-CONFLICT','EntryPoint March2026 brochure describes EP Third Moment InternationalLP as Cayman exempted limited partnership, but preserved2024-26FormD entityType saysCorporation. The brochure strengthens an as-filed LP representation, not independent Cayman corporate proof.',['CORP2-REG-BROCHURE'],['physical PDF p4 Item4'],status='unresolved_cross_filing_legal_form_conflict',other_evidence_pointer='Earlier sec-sources.json FormD originals0002016251-24-000001 through0002016251-26-000001')
add('CORP2-CIK-REJECTION','Official SEC submissions JSON identifies CIK1977777 as Cata Labs Inc., rejecting the third-party attribution of that identifier to EP Fund GP LLC.',['CORP2-SEC-CIK1977777'],['JSON $.name,$.cik,$.formerNames'],status='rejected_identifier_attribution',excluded_cik='1977777')
add('CORP2-NY-MEB','NY government data for DOS3772241 names MEB NY Inc., certificate of incorporation2009-02-06 and certificate of change2009-09-25. Status-history rows labelActive on those dates; current legal status and underlying change contents are not established.',['CORP2-NY-TARGET-FILINGS','CORP2-NY-TARGET-STATUS','CORP2-NY-TARGET-NAMES','CORP2-NY-DATA-DISCLAIMER'],['JSON rows corpid_num3772241; overview physical PDF pp2-3'],status='government_dataset_observation_subject_join_provisional')
add('CORP2-NY-PARTNERS','NY government data DOS6795220 names EntryPoint PartnersLP, Delaware foreign formation2020-08-17, authority filing2023-04-10 approved2023-04-11, publication filed2023-07-25 approved2023-07-26. Exact name, jurisdiction, kind and formation date correlate with Delaware3458856; regulator-to-corporate ownership-ID join remains provisional.',['CORP2-NY-TARGET-FILINGS','CORP2-BROWSERB-3'],['NY JSON rows corpid_num6795220; Delaware HTML entity-detail labelIDs'],status='correlated_corporate_identity_candidate',candidate_ids={'NY':'6795220','DE':'3458856'})
add('CORP2-NY-BEAUFORT','NY government data lists Ophir Partners Beaufort GP LLC DOS4790401 and Beaufort FundLP DOS4790408, foreign formation2015-07-14 in Delaware, both authority filings2015-07-16. These are corporate candidates; subject ownership join not established by this dataset.',['CORP2-NY-TARGET-FILINGS'],['JSON rows corpid_num4790401,4790408'],status='government_dataset_observation_subject_join_provisional')
add('CORP2-NY-DATES','NY entity-status/name-history datasets date Partners authority row2023-04-11 and publication row2023-07-26, matching approvals rather than all-filings dates2023-04-10 and2023-07-25. Preserve each dataset field and do not flatten into one universal filing date. Duplicate name-history rows do not mean two entities.',['CORP2-NY-TARGET-FILINGS','CORP2-NY-TARGET-STATUS','CORP2-NY-TARGET-NAMES'],['JSON rows corpid_num6795220'],status='source_field_semantics_variation')
add('CORP2-SEARCH-UNRESOLVED','Exact Delaware searches for EP FUND GP LLC and OPEH LLC returned no displayed matching rows in this bounded session. OPEH remains unlinked; EP Fund GP remains verified as a regulatory related person but corporate registry ID unresolved. This does not prove nonexistence in Delaware or elsewhere.',['CORP2-BROWSERB-14','CORP2-BROWSERB-16'],['HTML search result area'],status='bounded_negative_search_not_nonexistence_proof')
# Link each claim to its originals and retain separate candidate graph.
for s in sources:s['claim_links']=[c['claim_id'] for c in claims if s['document_id'] in c['source_ids']]
sp.write_text(json.dumps(sources,indent=2),encoding='utf8');(root/'claims.json').write_text(json.dumps(claims,indent=2),encoding='utf8');(root/'candidates.json').write_text(json.dumps(candidates,indent=2),encoding='utf8')
print('saved',len(claims),'claims',len(candidates),'registry candidates',len(sources),'source/attempt records; all saved-byte hashes checked')
